27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
58	    private Set<Pet> pets;
59	
60	    public String getAddress() {
61	        return this.address;
62	    }
63	
64	    public void setAddress(String address) {
65	        this.address = address;
66	    }
67	
68	    public String getCity() {
69	        return this.city;
70	    }
71	
72	    public void setCity(String city) {
73	        this.city = city;
74	    }
75	
76	    public String getTelephone() {
77	        return this.telephone;
78	    }
79	
80	    public void setTelephone(String telephone) {
81	        this.telephone = telephone;
82	    }
83	
84	    public String getEmail() {
85	        return this.email;
86	    }
87	
88	    public void setEmail(String email) {
89	        this.email = email;
90	    }
91	
92	    public LocalDate getRegistrationDate() {
93	        return this.registrationDate;
94	    }
95	
96	    public void setRegistrationDate(LocalDate registrationDate) {
97	        this.registrationDate = registrationDate;
98	    }
99	
100	    /**
101	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
102	     */
103	    @Transient
104	    public String getDisplayName() {
105	        return this.getLastName() + ", " + this.getFirstName();
106	    }
107	
108	    /**
109	     * Return this owner's initials as the upper-cased first letters of the first and last
110	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
111	     */
112	    @Transient
113	    public String getInitials() {
114	        return initial(this.getFirstName()) + initial(this.getLastName());
115	    }
116	
117	    private static String initial(String name) {
118	        return Character.toUpperCase(name.charAt(0)) + ".";
119	    }
120	
121	    protected Set<Pet> getPetsInternal() {
122	        if (this.pets == null) {
123	            this.pets = new HashSet<>();
124	        }
125	        return this.pets;
126	    }
127	
128	    protected void setPetsInternal(Set<Pet> pets) {
129	        this.pets = pets;
130	    }
131	
132	    public List<Pet> getPets() {
133	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
134	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
135	        return Collections.unmodifiableList(sortedPets);
136	    }
